    -- Token / cleanup
    local ENV = (typeof(getgenv) == "function" and getgenv()) or _G
    if type(ENV.__QVARIKS_CLIENT)=="table" and type(ENV.__QVARIKS_CLIENT.Stop)=="function" then
        pcall(ENV.__QVARIKS_CLIENT.Stop)
    end
    if type(ENV.__QVARIKS_V11)=="table" and type(ENV.__QVARIKS_V11.stop)=="function" then
        pcall(ENV.__QVARIKS_V11.stop)
    end
    ENV.__QCS2_TOKEN = (ENV.__QCS2_TOKEN or 0) + 1
    local TOKEN = ENV.__QCS2_TOKEN
    local function alive() return ENV.__QCS2_TOKEN == TOKEN end
    if ENV.__QCS2_CONNS then
        for _, c in ipairs(ENV.__QCS2_CONNS) do pcall(function() c:Disconnect() end) end
    end
    local Connections = {}
    ENV.__QCS2_CONNS = Connections
    local function track(c) if c then Connections[#Connections+1] = c end; return c end

    local function getHui()
        local ok, r = pcall(gethui); if ok and typeof(r)=="Instance" then return r end
        local ok2, c = pcall(function() return game:GetService("CoreGui") end)
        if ok2 and typeof(c)=="Instance" then return c end
    end
    local function mount(gui)
        local h = getHui()
        if h and pcall(function() gui.Parent = h end) then return true end
        return pcall(function() gui.Parent = PlayerGui end)
    end
    for _, root in ipairs({PlayerGui, getHui()}) do
        if root then pcall(function()
            for _, legacy in ipairs({GUI_NAME,"QVARIKS_ORIGINAL","QVARIKS_V10","QvariksCodeSniper","QvariksCodeSniperV2"}) do
                local old=root:FindFirstChild(legacy)
                if old then old:Destroy() end
            end
        end) end
    end

