    -- ==================== HELPERS ====================
    local styleInstance
    local function new(cls, props, parent)
        local o = Instance.new(cls)
        for k,v in pairs(props or {}) do o[k]=v end
        if styleInstance then styleInstance(o,props or {}) end
        if parent then o.Parent=parent end
        return o
    end
    local function corner(o, r)   return new("UICorner",{CornerRadius=UDim.new(0,r or 10)},o) end
    local function mkStroke(o, col, thick, trans)
        return new("UIStroke",{Color=col or C.stroke,Thickness=thick or 1,Transparency=trans or 0,ApplyStrokeMode=Enum.ApplyStrokeMode.Border},o)
    end
    local function tw(o, info, props)
        local ok, t = pcall(function() return TweenService:Create(o,info,props) end)
        if ok and t then t:Play(); return t end
    end

