    local soundsOn = true
    local function playSound(kind)
        if not soundsOn then return end
        local d = SOUNDS[kind] or SOUNDS.click
        pcall(function()
            local s = Instance.new("Sound")
            s.SoundId   = "rbxassetid://"..tostring(d[1])
            s.PlaybackSpeed = d[2]; s.Volume = d[3]
            s.Parent = SoundService; s:Play()
            Debris:AddItem(s, 3)
        end)
    end

