    local SAB_RECORDS, SAB_BY_NAME, SAB_QUERY_INDEX = {},{},{}
    local function normSAB(s)
        return tostring(s or ""):lower():gsub("[^%w%s\128-\255]"," "):gsub("%s+"," "):match("^%s*(.-)%s*$") or ""
    end
    local function parseIncome(s)
        local num,suf=s:match("^([%d%.]+)([KMB]?)/s$")
        if not num then return 0 end
        local scale=({K=1e3,M=1e6,B=1e9})[suf] or 1
        return tonumber(num)*scale
    end
    for raw in SAB_CATALOG:gmatch("[^\r\n]+") do
