            SAB_RECORDS[#SAB_RECORDS+1]=entry
            SAB_BY_NAME[normSAB(name)]=entry
        end
    end
    local function fmtSAB(r,mode)
        if mode=="income" then
            return r.name.." generates $"..r.income.." before mutations and traits."
        elseif mode=="rarity" then
            return r.name.." has "..r.rarity.." rarity."
        end
        return r.name.." is a "..r.rarity.." brainrot; base income $"..r.income.."."
    end
    -- The long, real question bank is indexed once, *not polled each frame*.
    -- Yielding after each 700 lines avoids blocking the renderer on low-end devices.
    local SABIndexStarted=false
    local function startSABIndex()
        if SABIndexStarted then return end
        SABIndexStarted=true
        task.spawn(function()
        local cnt=0
        for raw in SAB_QUESTION_CORPUS:gmatch("[^\r\n]+") do
            if not alive() then return end
            local question,idx,mode=raw:match("^([^\t]+)\t(%d+)\t(%a+)$")
            if question then
                local record=SAB_RECORDS[tonumber(idx)]
                if record then SAB_QUERY_INDEX[normSAB(question)]={record,mode} end
            end
            cnt=cnt+1
            if cnt%700==0 then task.wait() end
        end
        SAB_QUESTION_CORPUS=nil
        end)
    end
    local function hasAny(q,arr)
        for _,term in ipairs(arr) do if q:find(term,1,true) then return true end end
        return false
    end
    local function namedRecord(q)
        local longest,found=0,nil
        local bounded=" "..q.." "
        for name,rec in pairs(SAB_BY_NAME) do
            if #name>longest and bounded:find(" "..name.." ",1,true) then
                found,longest=rec,#name
            end
        end
        return found
    end
