        local suffix = addEnd and (" " .. addEnd:upper()) or ""

        local function ans(text) return text .. suffix end

        -- Name
        if ql:find("your name") or ql:find("what.*name") or ql:find("who are you") or ql:find("whats my name") or ql:find("what is my name") then
            if ql:find("my name") then
                -- "what's my name" = Sammy's name
                return ans("Your name is "..SAMMY.name.." (Roblox: "..SAMMY.roblox_username..")!")
            end
            return ans("This is the REVERSED.VS SAB knowledge resolver for Steal a Brainrot.")
        end
