            if ql:find("year") then return ans("Sammy was born in "..SAMMY.birth_year..".") end
            if ql:find("month") then return ans("Sammy's birth month is "..SAMMY.birth_month..".") end
            if ql:find("day") then return ans("Sammy's birthday is on a "..SAMMY.birth_day..".") end
            return ans("Sammy is "..SAMMY.age.." years old (born "..SAMMY.birth_month.." "..SAMMY.birth_year..").")
        end
