    function App.Number(value,default,minimum,maximum)
        local n=tonumber(value)
        if not n or n~=n or n==math.huge or n==-math.huge then return default end
        return math.clamp(n,minimum,maximum)
    end

    -- Every client-provided built-in font is offered; Unknown is not assignable.
    function App.BuildFontCatalog()
        local preferred={"Arcade","SciFi","Fantasy","Cartoon","Code","Bangers","Creepster",
            "FredokaOne","LuckiestGuy","PermanentMarker","SpecialElite","AmaticSC",
            "Antique","GrenzeGotisch","Fondamento","IndieFlower","PatrickHand","Kalam",
            "Michroma","Jura","Sarpanch","RobotoMono","Ubuntu","Oswald","Nunito",
            "Gotham","GothamMedium","GothamBold","GothamBlack","BuilderSans","BuilderSansMedium",
            "BuilderSansBold","BuilderSansExtraBold","Roboto","RobotoCondensed","JosefinSans",
            "DenkOne","Merriweather","TitilliumWeb","Bodoni","Garamond","Highway","Arimo",
            "ArimoBold","Arial","ArialBold","SourceSans","SourceSansBold","SourceSansLight",
            "SourceSansItalic","SourceSansSemibold","Legacy"}
        local byName={}
        local ok,items=pcall(function() return Enum.Font:GetEnumItems() end)
        if ok and type(items)=="table" then
            for _,item in ipairs(items) do
                if item.Name~="Unknown" then byName[item.Name]=item end
            end
        else
            for _,name in ipairs(preferred) do
                local found,item=pcall(function() return Enum.Font[name] end)
                if found and item then byName[name]=item end
            end
        end
        App.FontChoices={{Name="Default",Label="Default",Factor=1}}
        App.FontByName={Default=App.FontChoices[1]}
        local factors={Arcade=0.82,AmaticSC=1.18,Creepster=1.05,SpecialElite=0.95,Code=0.95}
        local function add(name)
            if not byName[name] or App.FontByName[name] then return end
            local item={Name=name,Label=name,Font=byName[name],Factor=factors[name] or 1}
            App.FontChoices[#App.FontChoices+1]=item;App.FontByName[name]=item
        end
        for _,name in ipairs(preferred) do add(name) end
        local rest={}
        for name in pairs(byName) do if not App.FontByName[name] then rest[#rest+1]=name end end
        table.sort(rest)
        for _,name in ipairs(rest) do add(name) end
    end

    function App.ApplyTextStyle(obj,metadata)
        if metadata.keep then return end
        local choice=App.FontByName[App.Layout.font] or App.FontByName.Default
        obj.Font=choice.Font or metadata.font
        obj.TextSize=math.max(8,math.floor(metadata.size*choice.Factor+0.5))
    end

    function App.RegisterStyle(obj,props)
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            -- Keep single-character navigation glyphs readable with any font.
            local glyph=props.Text=="−" or props.Text=="+" or props.Text=="R"
            local metadata={font=props.Font or obj.Font,size=props.TextSize or obj.TextSize or 14,keep=glyph}
            App.TextTargets[obj]=metadata
            App.ApplyTextStyle(obj,metadata)
        end
        local col=props.BackgroundColor3
        local surface=col and (col==C.bg or col==C.panel or col==C.card or col==C.cardHover or col==C.logBg)
        if obj:IsA("GuiObject") and surface then
            local base=props.BackgroundTransparency or 0
            if base<1 then
                App.SurfaceTargets[obj]=base
                obj.BackgroundTransparency=base+(1-base)*App.Layout.transparency
            end
        end
    end

    function App.KeepFont(obj,font,size)
        local metadata=App.TextTargets[obj]
        if metadata then metadata.keep=true end
        if font then obj.Font=font end
        if size then obj.TextSize=size end
        return obj
    end

    function App.SetFont(name,save)
        App.Layout.font=App.FontByName[name] and name or "Nunito"
        for obj,metadata in pairs(App.TextTargets) do
            if obj.Parent then App.ApplyTextStyle(obj,metadata) end
        end
        if App.UI.fontSelected then App.UI.fontSelected.Text="FONT · "..App.Layout.font end
        if App.UI.fontLabel then App.UI.fontLabel.Text="FONT STYLE  ·  "..App.Layout.font end
        for key,tile in pairs(App.UI.fontTiles or {}) do
            local active=key==App.Layout.font
            tile.stroke.Color=active and C.accent or C.stroke
            tile.stroke.Transparency=active and 0.05 or 0.45
            tile.marker.Visible=active
        end
        if save~=false then App.SaveSoon() end
    end

    function App.SetGlass(_value,save)
        App.Layout.transparency=0
        for obj,base in pairs(App.SurfaceTargets) do
            if obj.Parent then obj.BackgroundTransparency=base end
        end
        if App.UI.windowStroke then
            App.UI.windowStroke.Color=C.accent
            App.UI.windowStroke.Transparency=0.28
        end
        if App.UI.glassHighlight then
            App.UI.glassHighlight:Destroy()
            App.UI.glassHighlight=nil
        end
        if save~=false then App.SaveSoon() end
    end

    function App.Load()
        local payload
        if type(readfile)=="function" then
            local ok,raw=pcall(readfile,App.SavePath)
            if ok and type(raw)=="string" then
                local decoded,value=pcall(function() return HttpService:JSONDecode(raw) end)
                if decoded and type(value)=="table" then payload=value end
            end
        end
        payload=payload or ENV.__QVARIKS_AUTOSAVE
        -- Migrate the first populated legacy slot once; no Configs page is needed.
        if type(payload)~="table" and type(readfile)=="function" then
            local ok,raw=pcall(readfile,CONFIG_PATH)
            if ok and type(raw)=="string" then
                local decoded,slots=pcall(function() return HttpService:JSONDecode(raw) end)
                if decoded and type(slots)=="table" then
                    for _,slot in ipairs(slots) do
                        if type(slot)=="table" and type(slot.data)=="table" then
                            payload={settings=slot.data};break
                        end
                    end
                end
            end
        end
        if type(payload)~="table" then return end
        local options=type(payload.settings)=="table" and payload.settings or {}
        for key,default in pairs(App.Settings) do
            if type(default)=="boolean" and type(options[key])=="boolean" then
                App.Settings[key]=options[key]
            end
        end
        App.Settings.maxWords=math.floor(App.Number(options.maxWords,1,1,App.MaxWords))
        local layout=type(payload.layout)=="table" and payload.layout or {}
        App.Layout.x=App.Number(layout.x,0.5,0,1)
        App.Layout.y=App.Number(layout.y,0.5,0,1)
        App.Layout.scale=math.floor(App.Number(layout.scale,1,0.5,1.5)*20+0.5)/20
        App.Layout.page="Redeem"
        -- Always use a fully opaque black interface, ignoring legacy transparency settings.
        App.Layout.transparency=0
        App.Layout.font=type(layout.font)=="string" and App.FontByName[layout.font] and layout.font or "Nunito"
    end

    function App.SaveNow()
        if not App.Ready then return end
        local payload={schema=1,settings={},layout={}}
        for k,v in pairs(App.Settings) do payload.settings[k]=v end
        for k,v in pairs(App.Layout) do payload.layout[k]=v end
        ENV.__QVARIKS_AUTOSAVE=payload
        local ok,encoded=pcall(function() return HttpService:JSONEncode(payload) end)
        if not ok or encoded==App.LastSaved then return end
        if type(writefile)=="function" then
            local saved=pcall(writefile,App.SavePath,encoded)
            if saved then App.LastSaved=encoded end
            if App.UI.saveState then App.UI.saveState.Text=saved and "AUTO SAVE" or "SESSION SAVE" end
        elseif App.UI.saveState then
            App.UI.saveState.Text="SESSION SAVE"
        end
    end

    function App.SaveSoon()
        if not App.Ready then return end
        App.SaveRevision=App.SaveRevision+1
        local revision=App.SaveRevision
        task.delay(0.18,function()
            if alive() and revision==App.SaveRevision then App.SaveNow() end
        end)
    end

