            pill.BackgroundColor3=enabled and C.accent or C.off
            knob.BackgroundColor3=enabled and C.white or C.dim
            knob.Position=enabled and UDim2.fromOffset(23,3) or UDim2.fromOffset(3,3)
        end
        App.Controls[key]={Paint=paint,Row=row}
        hit.Activated:Connect(function()
            App.Settings[key]=not App.Settings[key]
            if key=="sounds" then soundsOn=App.Settings[key] end
            paint();playSound(App.Settings[key] and "on" or "off")
            if key=="detectCode" and not App.Settings[key] then App.Reset("Detection paused.") end
            if App.UpdateStatus then App.UpdateStatus() end
            if key=="autoRedeem" and App.Settings[key] then App.TrySubmit() end
            App.SaveSoon()
        end)
        paint()
    end

