    function App.UpdateStatus(message,color)
        local s=App.State
        App.UI.banner.Text=#s.words>0 and table.concat(s.words," ")
            or (s.collecting and "WAITING FOR WORD" or "WAITING FOR BANNER")
        App.UI.progress.Size=UDim2.new(#s.words/App.MaxWords,0,0,3)
        if not message then
            if not App.Settings.detectCode then message="DETECTION PAUSED"
            elseif not s.collecting then message="READY"
            elseif s.attempt then message="SUBMITTED · "..s.attempt.code;color=C.amber
            elseif s.cooldownUntil>os.clock() then message="WAITING FOR GAME COOLDOWN";color=C.amber
            elseif s.retryTarget>0 then message="WAITING FOR WORD "..s.retryTarget;color=C.amber
            else message="COLLECTING · "..#s.words.." / "..App.MaxWords end
        end
        App.UI.status.Text=message;App.UI.status.TextColor3=color or C.dim
    end

    -- ==================== REDEMPTION ====================
    function App.GetCodesUI()
        if App.Box and App.Box.Parent and App.Confirm and App.Confirm.Parent
            and App.Box:IsDescendantOf(PlayerGui) and App.Confirm:IsDescendantOf(PlayerGui) then
            return App.Box,App.Confirm
        end
        local codes=PlayerGui:FindFirstChild("Codes") or PlayerGui:FindFirstChild("Codes",true)
        if not codes then return end
        local redeem=codes:FindFirstChild("CodeRedeem",true)
        local box=redeem and redeem:FindFirstChildWhichIsA("TextBox",true)
            or codes:FindFirstChildWhichIsA("TextBox",true)
        local confirm=codes:FindFirstChild("Confirm",true) or codes:FindFirstChild("Submit",true)
        if confirm and not confirm:IsA("GuiButton") then confirm=confirm:FindFirstChildWhichIsA("GuiButton",true) end
        App.Box,App.Confirm=box,confirm
        -- Restyle the actual in-game code redeemer (not just this helper window).
        local redeemRoot=redeem or codes
        if redeemRoot and not redeemRoot:GetAttribute("ReversedVSStyled") then
            pcall(function()
                redeemRoot:SetAttribute("ReversedVSStyled",true)
                for _,obj in ipairs(redeemRoot:GetDescendants()) do
                    if obj:IsA("Frame") then
                        obj.BackgroundColor3=Color3.fromRGB(22,23,40)
                        obj.BorderSizePixel=0
                        if not obj:FindFirstChildOfClass("UICorner") then
                            local c=Instance.new("UICorner");c.CornerRadius=UDim.new(0,10);c.Parent=obj
                        end
                    elseif obj:IsA("TextBox") then
                        obj.BackgroundColor3=Color3.fromRGB(31,32,54)
                        obj.TextColor3=Color3.fromRGB(245,242,255)
                        obj.PlaceholderColor3=Color3.fromRGB(160,154,183)
                        obj.Font=Enum.Font.Nunito
                        obj.TextSize=math.max(obj.TextSize,15)
                        obj.BorderSizePixel=0
                        if not obj:FindFirstChildOfClass("UICorner") then
                            local c=Instance.new("UICorner");c.CornerRadius=UDim.new(0,9);c.Parent=obj
                        end
                    elseif obj:IsA("TextButton") then
                        obj.BackgroundColor3=Color3.fromRGB(125,82,220)
                        obj.TextColor3=Color3.fromRGB(255,255,255)
                        obj.Font=Enum.Font.Nunito
                        obj.TextSize=math.max(obj.TextSize,14)
                        obj.BorderSizePixel=0
                        if not obj:FindFirstChildOfClass("UICorner") then
                            local c=Instance.new("UICorner");c.CornerRadius=UDim.new(0,9);c.Parent=obj
                        end
                    elseif obj:IsA("TextLabel") then
                        obj.Font=Enum.Font.Nunito
                        if obj.TextColor3 then obj.TextColor3=Color3.fromRGB(238,233,255) end
                    end
                end
            end)
        end
        return box,confirm
    end

    -- Prepare the button signal before a code arrives. Refreshing in the background
    -- also handles games that add/remove handlers after creating the UI.
    function App.PrepareConfirm(button)
        if not button or not button.Parent then App.ConfirmPlan=nil;return end
        local plan
        if type(getconnections)=="function" then
            for _,name in ipairs({"Activated","MouseButton1Click","MouseButton1Down","MouseButton1Up"}) do
                local ok,list=pcall(function() return getconnections(button[name]) end)
                if ok and type(list)=="table" then
                    local enabled={}
                    for _,connection in ipairs(list) do
                        local inspected,active=pcall(function() return connection.Enabled end)
                        if not inspected or active~=false then enabled[#enabled+1]=connection end
                    end
                    if #enabled>0 then plan={button=button,name=name,connections=enabled};break end
                end
            end
        elseif type(firesignal)=="function" then
            plan={button=button,name="Activated",connections=nil}
        end
        App.ConfirmPlan=plan
        return plan
    end

    function App.FireConfirm(button)
        if not button or not button.Parent then return false end
        local plan=App.ConfirmPlan
        if not plan or plan.button~=button then plan=App.PrepareConfirm(button) end
        if not plan then return false end
        if plan.connections then
            local available=false
            for _,connection in ipairs(plan.connections) do
                local ok,enabled=pcall(function() return connection.Enabled end)
                if not ok or enabled~=false then available=true;break end
            end
            if not available then plan=App.PrepareConfirm(button) end
        end
        if not plan then return false end
        if type(firesignal)=="function" then
            local sent=pcall(function() firesignal(button[plan.name]) end)
            if sent then return true end
        end
        local sent=false
        for _,connection in ipairs(plan.connections or {}) do
            local ok,enabled=pcall(function() return connection.Enabled end)
            if not ok or enabled~=false then
                local fired=pcall(function() connection:Fire() end)
                sent=sent or fired
            end
        end
        if not sent then App.ConfirmPlan=nil end
        return sent
    end

    function App.Reset(reason,silent)
        local old=App.State
        App.State={generation=old.generation+1,words={},collecting=false,attempt=nil,
            stage=0,retryTarget=0,codeAt=0,riddleAt=0,riddleGeneration=old.riddleGeneration+1,
            cooldownUntil=old.cooldownUntil or 0,responses={}}
        if not silent then App.UpdateStatus() end
        if reason then App.Log(reason,"info") end
    end

    function App.Submit()
        local s=App.State
        if not alive() or not App.Settings.autoRedeem or not App.Settings.detectCode
            or not s.collecting or s.attempt or #s.words==0 then return end
        if #s.words<=s.stage then return end
        local remaining=s.cooldownUntil-os.clock()
        if remaining>0 then
            if not s.cooldownQueued then
                s.cooldownQueued=true
                task.delay(remaining+0.01,function()
                    if alive() and App.State==s then s.cooldownQueued=false;App.TrySubmit() end
                end)
            end
            App.UpdateStatus();return
        end
        local box,confirm=App.GetCodesUI()
        if not box or not confirm then
            s.waitingForUI=true
            App.UpdateStatus("OPEN THE GAME'S CODES PANEL",C.amber)
            return
        end
        local code=table.concat(s.words,"")
        local ok=pcall(function() box.Text=code end)
        if not ok or box.Text~=code then App.UpdateStatus("CODE INPUT UNAVAILABLE",C.red);return end
        local attempt={generation=s.generation,count=#s.words,code=code,at=os.clock()}
        local previousStage=s.stage
        -- Record first: an executor can invoke a game callback synchronously.
        s.responses=s.responses or {};s.responses[#s.responses+1]=attempt
        s.attempt=attempt;s.stage=attempt.count;s.retryTarget=0;s.waitingForUI=false
        if not App.FireConfirm(confirm) then
            if App.State==s and s.attempt==attempt then
                s.attempt=nil;s.stage=previousStage;s.waitingForUI=true
                if s.responses[#s.responses]==attempt then table.remove(s.responses) end
                if not s.handlerRetryQueued and (type(getconnections)=="function" or type(firesignal)=="function") then
                    s.handlerRetryQueued=true
                    task.delay(0.35,function()
                        if alive() and App.State==s then
                            s.handlerRetryQueued=false;App.PrepareConfirm(confirm);App.TrySubmit()
                        end
                    end)
                end
            end
            App.UpdateStatus("CONFIRM HANDLER UNAVAILABLE",C.red)
            return
        end
        App.Log("Sent: "..code,"info");playSound("submit")
        if App.State==s then App.UpdateStatus() end
        task.delay(App.ResultWait,function()
            if not alive() or App.State~=s or s.attempt~=attempt then return end
            s.attempt=nil
            if App.Settings.retryInvalid and #s.words>attempt.count then
                s.retryTarget=attempt.count+1;App.TrySubmit()
            else
                s.retryTarget=App.Settings.retryInvalid and math.min(attempt.count+1,App.MaxWords+1) or 0
                App.UpdateStatus("NO GAME RESPONSE · LISTENING",C.amber)
            end
        end)
    end

    function App.TrySubmit()
        local s=App.State
        if not App.Settings.autoRedeem or not s.collecting or s.attempt then return end
        local needed=s.retryTarget>0 and s.retryTarget or App.Settings.maxWords
        if #s.words>=needed and #s.words>s.stage then App.Submit() end
    end

    function App.Feedback(raw,kind,obj)
        local text=(App.Clean and App.Clean(raw) or tostring(raw or "")):lower()
        local invalid=text:find("invalid code",1,true) or text:find("wrong code",1,true)
            or text:find("code is invalid",1,true) or text:find("code expired",1,true)
        local success=text:find("successfully redeemed",1,true) or text:find("code redeemed",1,true)
            or text:find("code accepted",1,true)
        local used=text:find("already redeemed",1,true) or text:find("already used",1,true)
        local seconds=text:match("wait%s+(%d+)%s+more") or text:match("try again in%s+(%d+)")
        if invalid or success or used or seconds then
            if App.IsMirror and App.IsMirror("feedback:"..text,kind or "remote",obj,true) then return true end
        end
        local s=App.State
        if not (invalid or success or used or seconds) then return false end
        local responses=s.responses or {}
        while responses[1] and os.clock()-responses[1].at>12 do table.remove(responses,1) end
        -- Feedback has no attempt ID. Associate it with the oldest outstanding
        -- request so a late failure does not cancel a newer in-flight request.
        local attempt=table.remove(responses,1) or s.attempt
        if not s.collecting or not attempt then return true end
        if seconds then
            s.cooldownUntil=math.max(s.cooldownUntil,os.clock()+tonumber(seconds))
            s.stage=0;s.attempt=nil;s.responses={}
            App.TrySubmit();return true
        end
        if success or used then
            App.Reset(success and "Game confirmed redemption." or "Game says this code was already redeemed.")
            return true
        end
        if attempt~=s.attempt then return true end
        s.attempt=nil
        App.Log("Invalid: "..attempt.code,"warn")
        if not App.Settings.retryInvalid or attempt.count>=App.MaxWords then
            App.Reset("Attempt finished. Waiting for the next marker.")
        else
            s.retryTarget=attempt.count+1
            App.UpdateStatus();App.TrySubmit()
        end
        return true
    end


