    local RIDDLE_FACT_MAP={}
    local function normalizeRiddle(q)
        return tostring(q or ""):lower():gsub("<.->"," "):gsub("[^%w%s]"," "):gsub("%s+"," "):match("^%s*(.-)%s*$") or ""
    end
    for row in RIDDLE_QUESTION_FACTS:gmatch("[^\r\n]+") do
        local rawKeys,answer=row:match("^(.-)|([^|]+)")
        if rawKeys and answer then
            for key in rawKeys:gmatch("[^;]+") do
                local nk=normalizeRiddle(key)
                if #nk>=3 then RIDDLE_FACT_MAP[nk]=answer:upper():gsub("[^A-Z0-9]","") end
            end
        end
    end
    RIDDLE_QUESTION_FACTS=nil

    local function solveRiddle(prompt)
        local normalized=normalizeRiddle(prompt)
        local q=normalized:gsub("^the riddle is%s*",""):gsub("^riddle is%s*",""):
            gsub("^question%s*",""):gsub("^answer this%s*","")
        local suffix=""
        local base,x=q:match("^(.-)%s+and%s+add%s+(%w+)%s+at%s+the%s+end$")
        if not base then base,x=q:match("^(.-)%s+and%s+add%s+in%s+the%s+end%s+(%w+)$") end
        if not base then base,x=q:match("^(.-)%s+and%s+add%s+(%w+)%s+in%s+the%s+end$") end
        if not base then base,x=q:match("^(.-)%s+and%s+append%s+(%w+)$") end
        if base then q=base;suffix=x:upper() end
        if #q<3 then return nil end
        local ans=RIDDLE_FACT_MAP[q]
        local function all(...)
            for _,token in ipairs({...}) do if not q:find(token,1,true) then return false end end
            return true
        end
        if not ans then
            if all("favorite","brainrot") or all("favourite","brainrot") then ans="MEOWL"
            elseif all("favorite","color") or all("favourite","colour") then ans="BLUE"
            elseif all("favorite","food") then ans="PIZZA"
            elseif all("favorite","sport") then ans="FOOTBALL"
            elseif all("favorite","player") then ans="RONALDO"
            elseif all("favorite","number") then ans="67"
            elseif all("first","trait") then ans="LIGHTNING"
            elseif all("first","event") then ans="BLOODMOON"
            elseif all("where","born") then ans="ALGERIA"
            elseif all("birthday","year") then ans="2002"
            elseif all("birthday","month") then ans="FEBRUARY"
            elseif all("how","old","sammy") then ans="24"
            elseif all("co","owner") then ans="LUKE"
            elseif all("who","created","brainrot") then ans="SAMMY"
            elseif all("strongest","brainrot") or all("best","brainrot") then ans="SPYDERELEPHANT"
            elseif all("how","many","minifigure") then ans="10"
            elseif all("unobtainable","og") then ans="HEADLESSHORSEMAN"
            elseif all("lightning","trait","name") then ans="MATEO"
            elseif all("my","name") then ans="SAMMY"
            elseif all("my","username") then ans="SPYDERSAMMY"
            end
        end
        if not ans then
            local w=q:match("how many vowels in%s+([a-z]+)")
            if w then local _,n=w:gsub("[aeiou]","");ans=tostring(n) end
            w=q:match("how many letters in%s+([a-z]+)")
            if w then ans=tostring(#w) end
            w=q:match("reverse the word%s+([a-z]+)") or q:match("spell%s+([a-z]+)%s+backwards")
            if w then ans=w:reverse():upper() end
        end
        if not ans then
            local a,op,b=q:match("^what is%s+(%-?%d+)%s+([%a]+)%s+(%-?%d+)$")
            if a and b then
                a=tonumber(a);b=tonumber(b)
                local res
                if op=="plus" or op=="add" then res=a+b
                elseif op=="minus" then res=a-b
                elseif op=="times" or op=="multiplied" then res=a*b
                elseif op=="divided" and b~=0 then res=a/b end
                if res and math.abs(res)<1e12 and res==math.floor(res) then ans=tostring(res) end
            end
        end
        if not ans then return nil end
        local code=(tostring(ans)..suffix):upper():gsub("[^A-Z0-9]","")
        if #code<1 or #code>80 then return nil end
        return code
    end

    -- ==================== OCCURRENCE-BASED BANNER SCANNER ====================
    function App.Clean(raw)
        local text=tostring(raw or ""):gsub("<[^>]->","")
        text=text:gsub("&nbsp;"," "):gsub("&quot;",'"'):gsub("&apos;","'")
            :gsub("&amp;","&"):gsub("&lt;","<"):gsub("&gt;",">")
        text=text:gsub("\226\128\139",""):gsub("\239\187\191","")
        return text:gsub("[%c]"," "):gsub("%s+"," "):match("^%s*(.-)%s*$") or ""
    end

    -- Filters and marker grammar ported from the supplied traced redeemer.
    App.SystemPhrases={"code is","use code","font color","fontcolour","fontcolor","font colour","sammy has activated bubblegum machine","sammy activated 2x luck","sammy activated 6x luck","sammy activated 8x luck","sammy activated 10x luck","sammy activated 12x luck","sammy activated 15x luck","sammy activated 20x luck","sammy activated 25x luck","sammy activated 30x luck","sammy activated 35x luck","sammy activated","coins shop","brainrot trader","robux shop","robuxshop","spin wheel","spinwheel","trade plaza","tradeplaza","event has started","eventhasstarted","allowfriends","setcreatorid","to buy this","tobuythis","your base is already locked","your base is full","request failed","you locked your base for","you got a free spin","broke into your base","someone is stealing","trade has been completed","tradehasbeencompleted","event has been activated","has been activated","has activated","base is already locked","you locked your base","you have locked your base","locked your base","brainrot express has arrived","brainrot express has arrv","brainrot express leaving in"}
    App.SystemPrefixes={"sammy:","spydersammy:"}
    App.CodePatterns={"code%s+is","codes?%s+are","code%s+for","code%s+to%s+use","code%s*[:%-]","new%s+code","free%s+code","secret%s+code","working%s+code","another%s+code"}
    for _,lead in ipairs({"use","using","redeem","type","enter","claim","with","grab","got","here is","heres","here's","there is","theres","there's"}) do
        local pattern=lead:gsub("%s+","%%s+")
        for _,article in ipairs({"","the%s+","a%s+","an%s+","this%s+","your%s+","new%s+"}) do
            App.CodePatterns[#App.CodePatterns+1]=pattern.."%s+"..article.."code"
        end
    end
    function App.CompactText(text)
        return App.Clean(text):lower():gsub("[^%w]","")
    end
    App.CompactSystemPhrases={}
    for _,phrase in ipairs(App.SystemPhrases) do
        App.CompactSystemPhrases[#App.CompactSystemPhrases+1]={phrase=phrase,key=App.CompactText(phrase)}
    end
    function App.IsSystemText(text,includeMarkers)
        if not App.Settings.ignoreSystem then return false end
        local lower=App.Clean(text):lower()
        local noSpace=lower:gsub("%s+","")
        for _,prefix in ipairs(App.SystemPrefixes) do
            if noSpace:find(prefix,1,true) then return true,prefix end
        end
        local compact=App.CompactText(lower)
        for _,item in ipairs(App.CompactSystemPhrases) do
            if (includeMarkers or (item.phrase~="code is" and item.phrase~="use code"))
                and item.key~="" and compact:find(item.key,1,true) then return true,item.phrase end
        end
        return false
    end
    function App.CodeTail(text)
        for at,word in text:gmatch("()([%w_]+)") do
            if #word>=4 and word:match("%a") and (word:match("%u") or word:match("%d")) then
                return text:sub(at)
            end
        end
    end
    function App.CodeCandidate(text)
        local candidate
        for word in text:gmatch("[%w_]+") do
            if #word>=4 and word:match("%a") and (word:match("%u") or word:match("%d")) then candidate=word end
        end
        if candidate then return candidate end
        for word in text:gmatch("[%w_]+") do if #word>=4 then return word end end
    end
    function App.CodeMarker(raw)
        local text=App.Clean(raw)
        local lower=text:lower()
        local last,byName
        local function scan(pattern,plain,name)
            local start=1
            while true do
                local first,finish=lower:find(pattern,start,plain)
                if not first then break end
                if not last or finish>last then last=finish;byName=name end
                start=finish+1
            end
        end
        for _,pattern in ipairs(App.CodePatterns) do scan(pattern,false,false) end
        if lower:find("code",1,true) then scan("sammy",true,true) end
        if not last then return end
        local tail=App.CodeTail(text:sub(last+1))
        if byName and not tail then return end
        return last,tail or ""
    end
    function App.ClassifyDrop(text)
        local lower=text:lower()
        local words={}
        for word in text:gmatch("[%w']+") do words[#words+1]=word end
        local count=#words
        if count==0 then return end
        local spaced=" "..lower:gsub("[^%w]"," ").." "
        if lower:find("?",1,true) then return "riddle" end
        for _,word in ipairs({"what","how","which","whose","when","who","whats","where","why","guess","riddle","answer","my"}) do
            if spaced:find(" "..word.." ",1,true) then return "riddle" end
        end
        if count>=2 and (spaced:find(" plus ",1,true) or lower:find("+",1,true)) then return "riddle" end
        if count>=4 and spaced:find(" and ",1,true) then return "riddle" end
        if lower:find("code",1,true) then return "code" end
        for _,word in ipairs({"redeem","type","enter","claim"}) do
            if spaced:find(" "..word.." ",1,true) then return "code" end
        end
        if count>=7 then return "riddle" end
        if count==1 then return "code" end
        if count<=3 then
            for _,word in ipairs(words) do
                if #word<3 or not ((word==word:upper() and word:match("%a")) or word:match("%d")) then return end
            end
            return "code"
        end
    end

    function App.RiddleMarker(raw)
        local text=App.Clean(raw):lower():gsub("^the%s+","")
        return text:match("^riddle%s+is%f[%A]")~=nil or text:match("^riddle%s*:")~=nil
    end

    function App.RiddleQuestion(raw)
        return App.Clean(raw):gsub("^[Tt][Hh][Ee]%s+","")
            :gsub("^[Rr][Ii][Dd][Dd][Ll][Ee]%s+[Ii][Ss]%s*[:%-]?%s*","")
            :gsub("^[Rr][Ii][Dd][Dd][Ll][Ee]%s*:%s*","")
    end

    function App.ParseWords(raw)
        local text=App.Clean(raw)
        if text=="" or #text>App.MaxWordLength*App.MaxWords+16 or App.IsSystemText(text,true) then return end
        local tokens={}
        -- Same tokenizer as traced: preserve case, include digits/underscores.
        for word in text:gmatch("[%w_]+") do
            if #word>App.MaxWordLength or App.PhantomWords[word:upper()] then return end
            tokens[#tokens+1]=word
            if #tokens>App.MaxWords then return end
        end
        if #tokens>0 then return tokens end
    end

    function App.Root(obj)
        while obj and obj~=PlayerGui do
            if obj:IsA("ScreenGui") then return obj end
            obj=obj.Parent
        end
    end

    function App.BannerHint(obj)
        local depth=0
        while obj and obj~=PlayerGui and depth<9 do
            local name=obj.Name:lower()
            for _,part in ipairs({"top","announce","notify","notification","broadcast","banner",
                "alert","global","hint","message","riddle"}) do
                if name:find(part,1,true) then return true end
            end
            obj=obj.Parent;depth=depth+1
        end
        return false
    end

    function App.BannerContainer(obj)
        local original=obj
        while obj and obj~=PlayerGui do
            if obj~=original and App.BannerHint(obj) and not obj:IsA("ScreenGui") then return obj end
            if obj:IsA("ScreenGui") then return obj end
            obj=obj.Parent
        end
        return original and original.Parent
    end

    function App.Visible(obj,feedback)
        if not obj or not (obj:IsA("TextLabel") or obj:IsA("TextButton"))
            or not obj:IsDescendantOf(PlayerGui) or obj:IsDescendantOf(gui) then return false end
        local curr=obj
        while curr and curr~=PlayerGui do
            if curr:IsA("GuiObject") and not curr.Visible then return false end
            if curr:IsA("ScreenGui") and not curr.Enabled then return false end
            if curr:IsA("CanvasGroup") and curr.GroupTransparency>=1 then return false end
            if curr:IsA("TextBox") then return false end
            local name=curr.Name:lower()
            for _,part in ipairs({"chat","leaderboard","inventory","settings","textbox","search",
                "qvariks","reversed.vs"}) do
                if name:find(part,1,true) then return false end
            end
            if not feedback and (name:find("redeem",1,true) or name=="codes" or name=="shop") then return false end
            curr=curr.Parent
        end
        if obj.TextTransparency>=1 then return false end
        local camera=workspace.CurrentCamera
        if camera then
            local pos,size,vp=obj.AbsolutePosition,obj.AbsoluteSize,camera.ViewportSize
            if size.X<1 or size.Y<1 or pos.X+size.X<0 or pos.Y+size.Y<0 or pos.X>vp.X or pos.Y>vp.Y then return false end
            if not App.BannerHint(obj) and pos.Y>vp.Y*0.78 then return false end
        end
        return true
    end

    function App.Related(obj,riddle)
        if not obj then return true end
        local s=App.State
        local source=riddle and s.riddleSource or s.codeSource
        local container=riddle and s.riddleContainer or s.codeContainer
        if source==obj then return true end
        if container and obj:IsDescendantOf(container) then return true end
        if not source then return App.BannerHint(obj) end
        return App.Root(obj)==App.Root(source) and App.BannerHint(obj)
    end

    -- Overlapping text/shadow/outline labels are layers of the same display.
    -- Distinct banner containers and separate on-screen word positions stay separate.
    function App.PresentationRoot(obj)
        local parent=obj and obj.Parent
        local fallback=parent
        while parent and parent~=PlayerGui do
            if parent:IsA("ScreenGui") then return fallback or parent end
            local name=parent.Name:lower()
            for _,part in ipairs({"banner","announce","notify","notification","broadcast","alert","message","top"}) do
                if name:find(part,1,true) then return parent end
            end
            parent=parent.Parent
        end
        return fallback
    end

    function App.SamePresentation(a,b,compareText)
        if not a or not b or a==b or not a.Parent or not b.Parent then return false end
        if a.Parent~=b.Parent and App.PresentationRoot(a)~=App.PresentationRoot(b) then return false end
        local ap,bp,asz,bsz=a.AbsolutePosition,b.AbsolutePosition,a.AbsoluteSize,b.AbsoluteSize
        if math.abs(ap.X-bp.X)>6 or math.abs(ap.Y-bp.Y)>6
            or math.abs(asz.X-bsz.X)>12 or math.abs(asz.Y-bsz.Y)>12 then return false end
        if compareText then
            local function displayKey(label)
                local text=App.Clean(label.Text):upper()
                local marker,tail=App.CodeMarker(text)
                return marker and ("marker:"..tail:upper()) or text
            end
            return App.Visible(a,true) and App.Visible(b,true) and displayKey(a)==displayKey(b)
        end
        return true
    end

    -- One occurrence can have any number of visual layers. Track each label's
    -- text revision and token slot, instead of consuming a single 'mirrored' flag.
    -- Separate remote callbacks and fresh GUI text revisions remain occurrences.
    function App.IsMirror(key,kind,obj,anyGeneration,tokenSlot)
        local now=os.clock()
        for i=#App.Recent,1,-1 do
            local item=App.Recent[i]
            local feedback=item.key:sub(1,9)=="feedback:"
            local limit=feedback and App.MirrorWindow or App.CodeWindow
            if now-item.at>limit or (not feedback and item.generation~=App.State.generation
                and now-item.at>App.MirrorWindow) then table.remove(App.Recent,i) end
        end
        local guiEntry=obj and App.GUIEntries[obj]
        local version=guiEntry and guiEntry.textVersion or 0
        local slot=tokenSlot or 0
        local function markRemoteView(entry,label,view)
            local watched=label and App.GUIEntries[label]
            if watched then
                watched.remoteBacked=true;watched.remoteVersion=view.version
            end
        end
        for _,entry in ipairs(App.Recent) do
            local sameSession=entry.generation==App.State.generation
            local fadingCopy=kind=="gui" and entry.remoteSeen and now-entry.at<=App.MirrorWindow
            if (anyGeneration or sameSession or fadingCopy) and entry.key==key then
                if kind=="remote" and not entry.remoteSeen then
                    entry.remoteSeen=true
                    for label,view in pairs(entry.views) do markRemoteView(entry,label,view) end
                    return true,entry
                elseif kind=="gui" and obj then
                    local view=entry.views[obj]
                    if view then
                        if entry.remoteSeen and view.version==version and view.slot==slot then return true,entry end
                    else
                        local copy=entry.remoteSeen and not entry.primary
                        if entry.primary then
                            copy=App.SamePresentation(entry.primary,obj,not entry.remoteSeen)
                            if entry.remoteSeen and not entry.primary.Parent and now-entry.at<=App.MirrorWindow then copy=true end
                        end
                        if copy then
                            local newView={version=version,slot=slot}
                            entry.views[obj]=newView
                            if not entry.primary or not entry.primary.Parent then entry.primary=obj end
                            if entry.remoteSeen then markRemoteView(entry,obj,newView) end
                            return true,entry
                        end
                    end
                end
            end
        end
        local entry={key=key,kind=kind,at=now,generation=App.State.generation,
            remoteSeen=kind=="remote",primary=obj,views=setmetatable({},{__mode="k"})}
        if obj then entry.views[obj]={version=version,slot=slot} end
        App.Recent[#App.Recent+1]=entry
        if #App.Recent>96 then table.remove(App.Recent,1) end
        return false,entry
    end

    function App.BindCodeSource(obj,remote)
        local s=App.State
        if obj and (not s.codeSource or not s.codeSource.Parent) then
            s.codeSource=obj;s.codeContainer=App.BannerContainer(obj)
        end
        if remote then s.codeRemote=remote end
    end

    function App.BeginCode(obj,remote)
        App.Reset(nil,true)
        local s=App.State
        s.collecting=true;s.codeAt=os.clock()
        App.BindCodeSource(obj,remote)
        local generation=s.generation
        task.delay(App.CodeWindow,function()
            if alive() and App.State.generation==generation and App.State.collecting then
                App.Reset("Banner session expired.")
            end
        end)
        -- UI work is deferred so the attached code can be submitted first.
        task.defer(function()
            if alive() and App.State==s then
                App.UpdateStatus();App.Log("New code marker · input restarted.","success")
            end
        end)
    end

    function App.RecordWords(raw,obj,kind,remote,top)
        -- No GUI text, text boxes, generic remotes or implicit channel inheritance.
        if obj~=nil or kind~="remote" or top~=true or not App.IsAnnouncementRemote(remote) then return end
        local s=App.State
        if not s.collecting or not App.Settings.detectCode or s.codeRemote~=remote
            or os.clock()-s.codeAt>App.CodeWindow then return end
        local tokens=App.ParseWords(raw)
        if not tokens then return end
        local added={}
        for index,word in ipairs(tokens) do
            if not App.IsMirror("word:"..word,"remote",nil,false,index) and #s.words<App.MaxWords then
                s.words[#s.words+1]=word
                added[#added+1]={index=#s.words,word=word}
            end
        end
        if #added>0 then
            App.TrySubmit()
            App.UpdateStatus()
            for _,item in ipairs(added) do
                App.Log("Word "..item.index.."/"..App.MaxWords.." [Announcement/Top]: "..item.word,"word")
            end
        end
    end

    function App.SubmitRiddle(raw)
        local s=App.State
        if not App.Settings.autoRiddle then return end
        local question=App.RiddleQuestion(raw)
        if #question<4 or #question>420 or App.CodeMarker(question) then return end
        if question==s.lastRiddleQuestion then return end
        local answer=solveRiddle(question)
        if not answer then return end
        local box,confirm=App.GetCodesUI()
        if not box or not confirm then App.Log("Riddle answer ready: "..answer.." · open Codes.","warn");return end
        if os.clock()<s.cooldownUntil then return end
        local ok=pcall(function() box.Text=answer end)
        if ok and box.Text==answer and App.FireConfirm(confirm) then
            s.lastRiddleQuestion=question
            App.Log("Riddle answer sent: "..answer,"info")
        end
    end

    function App.OnAnnouncement(raw,obj,kind,remote,top)
        -- This gate is repeated here so no GUI/fallback caller can start a session.
        if not alive() or obj~=nil or kind~="remote" or top~=true
            or not App.IsAnnouncementRemote(remote) or type(raw)~="string" or #raw>600
            or not (App.Settings.detectCode or App.Settings.autoRiddle) then return end
        local text=App.Clean(raw)
        if text=="" or App.Feedback(text,"remote") then return end
        local system,reason=App.IsSystemText(text,false)
        -- The reference allows an initial Sammy-prefixed trigger, then filters
        -- sender-prefixed messages once collection has started.
        local initialPrefix=not App.State.collecting and (reason=="sammy:" or reason=="spydersammy:")
        if system and not initialPrefix then return end
        local marker,tail=App.CodeMarker(text)
        if marker and App.Settings.detectCode then
            local mirrored,occurrence=App.IsMirror("marker:"..tail:upper(),"remote")
            if mirrored then return end
            App.BeginCode(nil,remote)
            occurrence.generation=App.State.generation
            if tail~="" then App.RecordWords(tail,nil,"remote",remote,true) end
            return
        end
        local classification=App.ClassifyDrop(text)
        if not marker and (App.RiddleMarker(text) or classification=="riddle") then
            if not App.Settings.autoRiddle then return end
            local mirrored,occurrence=App.IsMirror("riddle:"..text:upper(),"remote")
            if not mirrored then
                App.Reset()
                local s=App.State
                s.riddleAt=os.clock();s.riddleRemote=remote;occurrence.generation=s.generation
                App.Log("Riddle [Announcement/Top].","info");App.SubmitRiddle(text)
            end
            return
        end
        local s=App.State
        if s.riddleAt>0 and s.riddleRemote==remote and os.clock()-s.riddleAt<App.RiddleWindow then
            App.SubmitRiddle(text);return
        end
        if s.collecting and classification=="code" and not App.IsSystemText(text,true) then
            App.RecordWords(text,nil,"remote",remote,true)
        end
    end

    -- GUI is used ONLY for game redemption feedback, never as a code source.
    function App.IsCodeFeedbackLabel(obj)
        if not obj or not obj:IsA("TextLabel") or not obj:IsDescendantOf(PlayerGui)
            or obj:IsDescendantOf(gui) then return false end
        local curr=obj.Parent
        while curr and curr~=PlayerGui do
            if curr:IsA("TextBox") then return false end
            if curr.Name=="Codes" then return true end
            curr=curr.Parent
        end
        return false
    end

    function App.QueueLabel(obj)
        local entry=App.GUIEntries[obj]
        if not entry or not obj.Parent or not App.IsCodeFeedbackLabel(obj) then return end
        if not App.Visible(obj,true) then entry.wasVisible=false;return end
        local text=App.Clean(obj.Text)
        if entry.wasVisible and entry.raw==text then return end
        entry.raw=text;entry.wasVisible=true
        if text~="" then App.Feedback(text,"gui",obj) end
    end

    function App.RecheckTree(root)
        if App.GUIEntries[root] then App.QueueLabel(root) end
        for _,obj in ipairs(root:GetDescendants()) do
            if App.GUIEntries[obj] then App.QueueLabel(obj) end
        end
    end

    function App.WatchAncestors(obj)
        local curr=obj
        while curr and curr~=PlayerGui do
            if not App.Ancestors[curr] then
                App.Ancestors[curr]=true
                local ancestor=curr
                local property=curr:IsA("ScreenGui") and "Enabled" or (curr:IsA("GuiObject") and "Visible" or nil)
                if property then
                    track(curr:GetPropertyChangedSignal(property):Connect(function() App.RecheckTree(ancestor) end))
                end
                if curr:IsA("CanvasGroup") then
                    track(curr:GetPropertyChangedSignal("GroupTransparency"):Connect(function() App.RecheckTree(ancestor) end))
                end
            end
            curr=curr.Parent
        end
    end

    function App.WatchText(obj)
        if App.GUIEntries[obj] or not App.IsCodeFeedbackLabel(obj) then return end
        local entry={raw=App.Clean(obj.Text),wasVisible=App.Visible(obj,true),textVersion=0}
        App.GUIEntries[obj]=entry
        track(obj:GetPropertyChangedSignal("Text"):Connect(function()
            entry.textVersion=entry.textVersion+1;App.QueueLabel(obj)
        end))
        track(obj:GetPropertyChangedSignal("TextTransparency"):Connect(function() App.QueueLabel(obj) end))
        track(obj.AncestryChanged:Connect(function() App.QueueLabel(obj) end))
        App.WatchAncestors(obj)
    end

    track(PlayerGui.DescendantAdded:Connect(function(obj)
        App.WatchText(obj)
        if obj:IsA("TextBox") or obj:IsA("GuiButton") then
            -- Rebuilt Codes panels can immediately consume a code waiting for UI.
            task.defer(function()
                if not alive() then return end
                local _,confirm=App.GetCodesUI()
                if confirm and (not App.ConfirmPlan or App.ConfirmPlan.button~=confirm) then
                    App.PrepareConfirm(confirm)
                end
                if App.State.waitingForUI then App.TrySubmit() end
            end)
        end
    end))
    task.spawn(function()
        local count=0
        for _,obj in ipairs(PlayerGui:GetDescendants()) do
            if not alive() then return end
            App.WatchText(obj);count=count+1
            if count%200==0 then task.wait() end
        end
    end)

    -- ==================== REMOTE BANNER FAST PATH ====================
    function App.NotificationNet()
        local packages=ReplicatedStorage:FindFirstChild("Packages")
        return packages and packages:FindFirstChild("Net")
    end
    function App.ResolveNotificationRemote()
        local net=App.NotificationNet()
        local controllers=ReplicatedStorage:FindFirstChild("Controllers")
        local module=controllers and controllers:FindFirstChild("NotificationController",true)
        local getter=(debug and debug.getupvalues) or getupvalues
        if not net or not module or type(getter)~="function" then return end
        local ok,controller=pcall(require,module)
        if not ok or type(controller)~="table" or type(controller.Start)~="function" then return end
        local got,values=pcall(getter,controller.Start)
        if not got or type(values)~="table" then return end
        -- Same discovery as the reference: the remote captured by Start under Net.
        for _,obj in pairs(values) do
            if typeof(obj)=="Instance" and obj.Parent==net
                and (obj:IsA("RemoteEvent") or obj:IsA("UnreliableRemoteEvent")) then return obj end
        end
    end
    function App.IsAnnouncementRemote(obj)
        if not obj or not (obj:IsA("RemoteEvent") or obj:IsA("UnreliableRemoteEvent"))
            or not obj:IsDescendantOf(ReplicatedStorage) then return false end
        if App.NotificationRemote and App.NotificationRemote.Parent then return obj==App.NotificationRemote end
        -- Narrow fallback if this executor cannot inspect controller upvalues.
        local name=obj.Name:lower()
        return name=="announcement" or name=="announcements"
            or name=="re/announcement" or name=="re/announcements"
    end
    function App.RemotePacket(args)
        -- Traced strict mode: ONLY text arg 1 and channel Top in arg 4.
        if type(args[1])~="string" or args[4]~="Top" or #args[1]==0 or #args[1]>600 then
            return {messages={},top=false}
        end
        return {messages={args[1]},top=true}
    end

    function App.OnRemote(remote,...)
        if not alive() or not App.IsAnnouncementRemote(remote) then return end
        local packet=App.RemotePacket(table.pack(...))
        -- No marker-based bypass, bound-remote bypass, or Top-like channel aliases.
        if not packet.top then return end
        local last=App.LastRemoteNotice
        local text=packet.messages[1]
        local now=os.clock()
        if last and last.remote==remote and last.text==text and now-last.at<0.25 then return end
        App.LastRemoteNotice={remote=remote,text=text,at=now}
        for _,text in ipairs(packet.messages) do
            App.OnAnnouncement(text,nil,"remote",remote,true)
        end
    end

    function App.HookRemote(obj)
        if App.Remotes[obj] or not App.IsAnnouncementRemote(obj) then return end
        local ok,connection=pcall(function()
            return obj.OnClientEvent:Connect(function(...) App.OnRemote(obj,...) end)
        end)
        if ok and connection then App.Remotes[obj]=true;track(connection) end
    end
    function App.RefreshAnnouncementSource()
        if not alive() then return end
        local remote=App.ResolveNotificationRemote()
        if remote then
            App.NotificationRemote=remote
            App.HookRemote(remote)
        end
    end
    App.NotificationRemote=App.ResolveNotificationRemote()
    track(ReplicatedStorage.DescendantAdded:Connect(function(obj)
        App.HookRemote(obj)
        if not App.SourceSearchQueued and (not App.NotificationRemote or not App.NotificationRemote.Parent) then
            if obj.Name=="NotificationController" or obj:IsA("RemoteEvent") or obj:IsA("UnreliableRemoteEvent") then
                App.SourceSearchQueued=true
                task.defer(function() App.SourceSearchQueued=false;App.RefreshAnnouncementSource() end)
            end
        end
    end))
    for _,obj in ipairs(ReplicatedStorage:GetDescendants()) do App.HookRemote(obj) end
    for _,delay in ipairs({1,3,8}) do task.delay(delay,App.RefreshAnnouncementSource) end


    -- ==================== POSITION / VIEWPORT FIT ====================

    function App.Viewport()
        local camera=workspace.CurrentCamera
        local vp=camera and camera.ViewportSize or Vector2.new(1280,720)
        return Vector2.new(math.max(1,vp.X),math.max(1,vp.Y))
    end

    function App.Fit()
        local vp=App.Viewport()
        local scale=math.max(0.05,math.min(App.Layout.scale,(vp.X-20)/App.Width,(vp.Y-20)/App.Height))
        App.UI.scale.Scale=scale
        local halfX=math.min(0.5,(App.Width*scale/2+8)/vp.X)
        local halfY=math.min(0.5,(App.Height*scale/2+8)/vp.Y)
        App.Layout.x=math.clamp(App.Layout.x,halfX,1-halfX)
        App.Layout.y=math.clamp(App.Layout.y,halfY,1-halfY)
        App.UI.window.Position=UDim2.fromScale(App.Layout.x,App.Layout.y)
    end

    App.Drag={active=false}
    track(App.UI.top.InputBegan:Connect(function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        App.Drag={active=true,input=input,startX=input.Position.X,startY=input.Position.Y,
            x=App.Layout.x,y=App.Layout.y}
    end))
    track(UserInputService.InputChanged:Connect(function(input)
        local drag=App.Drag
        if not drag.active then return end
        local mouse=drag.input.UserInputType==Enum.UserInputType.MouseButton1
            and input.UserInputType==Enum.UserInputType.MouseMovement
        if not mouse and input~=drag.input then return end
        local vp=App.Viewport()
        App.Layout.x=drag.x+(input.Position.X-drag.startX)/vp.X
        App.Layout.y=drag.y+(input.Position.Y-drag.startY)/vp.Y
        App.Fit();App.SaveSoon()
    end))
    track(UserInputService.InputEnded:Connect(function(input)
        if App.Drag.active and input==App.Drag.input then
            App.Drag.active=false;App.SaveNow()
        end
    end))

    function App.HookCamera()
        if App.CameraConnection then App.CameraConnection:Disconnect() end
        local camera=workspace.CurrentCamera
        if camera then
            App.CameraConnection=track(camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                App.Fit();App.SaveSoon()
            end))
        end
    end
    track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        App.HookCamera();App.Fit();App.SaveSoon()
    end))
    App.HookCamera();App.Fit()

    -- ==================== MINIMIZE / CLEANUP ====================
    App.UI.open=new("TextButton",{Name="OpenReversedVS",AnchorPoint=Vector2.new(1,1),
        Position=UDim2.new(1,-18,1,-18),Size=UDim2.fromOffset(48,48),BackgroundColor3=C.card,
        BorderSizePixel=0,AutoButtonColor=false,Text="R",Font=Enum.Font.GothamBold,TextSize=19,
        TextColor3=C.white,Visible=false},gui)
    corner(App.UI.open,14);mkStroke(App.UI.open,C.stroke,1)
    function App.SetOpen(open)
        if not open and App.ReleaseSlider then App.ReleaseSlider() end
        App.UI.window.Visible=open;App.UI.open.Visible=not open
        App.SaveNow()
    end
    App.UI.close.Activated:Connect(function() App.SetOpen(false) end)
    App.UI.open.Activated:Connect(function() App.SetOpen(true) end)
    track(UserInputService.InputBegan:Connect(function(input,processed)
        if processed or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode==Enum.KeyCode.RightControl then App.SetOpen(not App.UI.window.Visible) end
    end))

    function App.Stop()
        if App.Stopped then return end
        if App.ReleaseSlider then App.ReleaseSlider() end
        App.SaveNow();App.Stopped=true
        if App.Overhead then pcall(function() App.Overhead:Destroy() end);App.Overhead=nil end
        if ENV.__QCS2_TOKEN==TOKEN then ENV.__QCS2_TOKEN=TOKEN+1 end
        for _,connection in ipairs(Connections) do pcall(function() connection:Disconnect() end) end
        if gui.Parent then gui:Destroy() end
        if ENV.__QVARIKS_CLIENT==App then ENV.__QVARIKS_CLIENT=nil end
    end
    ENV.__QVARIKS_CLIENT=App
    track(gui.Destroying:Connect(function()
        if App.ReleaseSlider then App.ReleaseSlider() end
        App.SaveNow()
    end))
    if LP.OnTeleport then track(LP.OnTeleport:Connect(function() App.SaveNow() end)) end

    -- ==================== PLAYER OVERHEAD TAG ====================
    local function AttachOverheadTag(character)
        if not character then return end
        task.spawn(function()
            local head=character:WaitForChild("Head",8)
            if not head or not alive() then return end
            local previous=head:FindFirstChild("ReversedVSOverhead")
            if previous then previous:Destroy() end
            local billboard=Instance.new("BillboardGui")
            billboard.Name="ReversedVSOverhead"
            billboard.Adornee=head
            billboard.AlwaysOnTop=true
            billboard.LightInfluence=0
            billboard.Size=UDim2.fromOffset(360,64)
            billboard.StudsOffset=Vector3.new(0,3.15,0)
            billboard.Parent=head
            local label=Instance.new("TextLabel")
            label.BackgroundTransparency=1
            label.Size=UDim2.fromScale(1,1)
            label.Font=Enum.Font.Nunito
            label.Text=".gg/QGv6ywpnNG"
            label.TextColor3=Color3.fromRGB(255,255,255)
            label.TextSize=30
            label.TextStrokeColor3=Color3.fromRGB(0,0,0)
            label.TextStrokeTransparency=0.25
            label.Parent=billboard
            App.Overhead=billboard
        end)
    end
    if LP.Character then AttachOverheadTag(LP.Character) end
    track(LP.CharacterAdded:Connect(AttachOverheadTag))

    App.SetFont("Nunito",false)
    App.SetGlass(0,false)
    App.Ready=true
    App.ShowPage("Redeem")
    App.GetCodesUI()
    App.UpdateStatus()
    App.SaveSoon()
    App.Log("Ready · remote + GUI banner listeners.","success")

    -- ==================== REVERSED.VS INTRO ====================
    -- The requested intro image is loaded directly from the supplied URL.
    local function ResolveIntroImage()
        if type(game.HttpGet) == "function" and type(writefile) == "function" then
            local ok,body=pcall(function() return game:HttpGet(INTRO_IMAGE_URL) end)
            if ok and type(body)=="string" and #body>0 then
                local file="REVERSED_VS_intro.png"
                local saved=pcall(writefile,file,body)
                if saved then
                    local assetFns={getcustomasset,getsynasset}
                    for _,fn in pairs(assetFns) do
                        if type(fn)=="function" then
                            local good,asset=pcall(fn,file)
                            if good and type(asset)=="string" and asset~="" then return asset end
                        end
                    end
                end
            end
        end
        -- Roblox ImageLabel cannot render arbitrary https URLs directly.
        return ""
    end

    local function ResolveIntroSound()
        -- Roblox catalog audio ID supplied by the user.
        return INTRO_SOUND_ID
    end

    local function PlayIntro()
        local overlay,sound
        pcall(function()
            overlay=Instance.new("Frame")
            overlay.Name="ReversedVSIntro"
            overlay.Size=UDim2.fromScale(1,1)
            overlay.Position=UDim2.fromScale(0,0)
            overlay.BackgroundColor3=Color3.fromRGB(0,0,0)
            overlay.BackgroundTransparency=0
            overlay.BorderSizePixel=0
            overlay.ZIndex=100
            overlay.Parent=gui

            local logo=Instance.new("ImageLabel")
            logo.Name="IntroImage"
            logo.AnchorPoint=Vector2.new(0.5,0.5)
            logo.Position=UDim2.fromScale(0.5,0.5)
            logo.Size=UDim2.fromScale(1,1)
            logo.BackgroundTransparency=1
            logo.BorderSizePixel=0
            logo.Image=ResolveIntroImage()
            logo.ScaleType=Enum.ScaleType.Crop
            logo.ImageTransparency=1
            logo.ZIndex=101
            logo.Parent=overlay

            local soundAsset=ResolveIntroSound()
            if soundAsset then
                sound=Instance.new("Sound")
                sound.Name="ReversedVSIntroSound"
                sound.Volume=0.8
                sound.SoundId=soundAsset
                sound.Parent=SoundService
                pcall(function() sound:Play() end)
            end

            TweenService:Create(logo,TweenInfo.new(0.35,Enum.EasingStyle.Quad,
                Enum.EasingDirection.Out),{ImageTransparency=0}):Play()
            task.wait(3)
        end)
        if sound then pcall(function() sound:Stop();sound:Destroy() end) end
        if overlay and overlay.Parent then overlay:Destroy() end
        if alive() and App.UI.window and App.UI.window.Parent then
            App.UI.window.Visible=true
            App.UI.open.Visible=false
        end
    end

    task.spawn(PlayIntro)
    task.spawn(function()
        while alive() do
            local _,confirm=App.GetCodesUI()
            if confirm then
                App.PrepareConfirm(confirm)
                if App.State.waitingForUI then App.TrySubmit() end
            end
            task.wait(0.8)
        end
    end)
